package com.sahyadri.sahyadripooltrip.controller;
import com.sahyadri.sahyadripooltrip.service.NatureDestinationCsvImportService; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/destinations/import") public class NatureDestinationImportController{private final NatureDestinationCsvImportService s;public NatureDestinationImportController(NatureDestinationCsvImportService s){this.s=s;}@PostMapping public ResponseEntity<Map<String,Object>> run(){try{var r=s.importAll();return ResponseEntity.ok(Map.of("success",true,"locationCount",r.locationCount(),"message","India nature + special destination master imported successfully."));}catch(Exception e){return ResponseEntity.internalServerError().body(Map.of("success",false,"message","Nature destination import failed","error",String.valueOf(e.getMessage())));}}}
